"use client";
import { useEffect, useState } from 'react';
import { useRouter, useSearchParams } from 'next/navigation';

export default function GoogleCallbackPage() {
  const router = useRouter();
  const searchParams = useSearchParams();
  const [status, setStatus] = useState('processing');
  const [error, setError] = useState('');

  useEffect(() => {
    const handleCallback = async () => {
      try {
        // Obtener código de autorización de Google
        const code = searchParams.get('code');
        const error = searchParams.get('error');
        const state = searchParams.get('state');

        if (error) {
          throw new Error(`Error de Google: ${error}`);
        }

        if (!code) {
          throw new Error('Código de autorización no recibido');
        }

        if (state !== 'mobile_auth') {
          throw new Error('Estado de autorización inválido');
        }

        setStatus('exchanging');

        // Intercambiar código por token usando nuestro backend
        const response = await fetch('/api/auth/google/exchange', {
          method: 'POST',
          headers: {
            'Content-Type': 'application/json',
          },
          body: JSON.stringify({ code })
        });

        if (!response.ok) {
          throw new Error('Error intercambiando código por token');
        }

        const data = await response.json();

        if (!data.user || !data.token) {
          throw new Error('Datos de usuario incompletos');
        }

        // Crear sesión
        const sessionData = {
          user: data.user,
          token: data.token,
          refreshToken: data.refreshToken,
          expires: new Date(Date.now() + 30 * 24 * 60 * 60 * 1000).toISOString(),
          created: new Date().toISOString()
        };

        // Guardar en localStorage
        localStorage.setItem('bisonte_mobile_session', JSON.stringify(sessionData));
        localStorage.setItem('user', JSON.stringify(data.user));
        localStorage.setItem('authToken', data.token);

        setStatus('success');

        // Redirigir al home después de un breve delay
        setTimeout(() => {
          router.push('/home');
        }, 1500);

      } catch (err) {
        console.error('Error en callback de Google:', err);
        setError(err.message);
        setStatus('error');

        // Redirigir al login después de mostrar error
        setTimeout(() => {
          router.push('/login?error=google_auth_failed');
        }, 3000);
      }
    };

    handleCallback();
  }, [searchParams, router]);

  const getStatusMessage = () => {
    switch (status) {
      case 'processing':
        return 'Procesando autenticación...';
      case 'exchanging':
        return 'Intercambiando credenciales...';
      case 'success':
        return '¡Autenticación exitosa!';
      case 'error':
        return error || 'Error en autenticación';
      default:
        return 'Procesando...';
    }
  };

  const getStatusColor = () => {
    switch (status) {
      case 'success':
        return '#10b981'; // green
      case 'error':
        return '#ef4444'; // red
      default:
        return '#3b82f6'; // blue
    }
  };

  return (
    <html>
      <body>
        <div style={{
          minHeight: '100vh',
          backgroundColor: '#111827',
          display: 'flex',
          alignItems: 'center',
          justifyContent: 'center',
          padding: '16px'
        }}>
          <div style={{ 
            textAlign: 'center',
            maxWidth: '400px',
            width: '100%'
          }}>
            {status !== 'error' && (
              <div style={{
                width: '48px',
                height: '48px',
                border: '4px solid #e5e7eb',
                borderTop: `4px solid ${getStatusColor()}`,
                borderRadius: '50%',
                animation: 'spin 1s linear infinite',
                margin: '0 auto 24px'
              }}></div>
            )}
            
            {status === 'error' && (
              <div style={{
                width: '48px',
                height: '48px',
                backgroundColor: '#ef4444',
                borderRadius: '50%',
                display: 'flex',
                alignItems: 'center',
                justifyContent: 'center',
                margin: '0 auto 24px'
              }}>
                <span style={{ color: 'white', fontSize: '24px' }}>✕</span>
              </div>
            )}

            {status === 'success' && (
              <div style={{
                width: '48px',
                height: '48px',
                backgroundColor: '#10b981',
                borderRadius: '50%',
                display: 'flex',
                alignItems: 'center',
                justifyContent: 'center',
                margin: '0 auto 24px'
              }}>
                <span style={{ color: 'white', fontSize: '24px' }}>✓</span>
              </div>
            )}

            <p style={{ 
              color: 'white', 
              fontSize: '18px',
              marginBottom: '8px',
              fontWeight: '500'
            }}>
              {getStatusMessage()}
            </p>

            {status === 'error' && (
              <p style={{ 
                color: '#9ca3af', 
                fontSize: '14px',
                lineHeight: '1.5'
              }}>
                Serás redirigido al login en unos segundos...
              </p>
            )}

            {status === 'success' && (
              <p style={{ 
                color: '#9ca3af', 
                fontSize: '14px',
                lineHeight: '1.5'
              }}>
                Redirigiendo al inicio...
              </p>
            )}
          </div>
        </div>
        
        <style dangerouslySetInnerHTML={{
          __html: `
            @keyframes spin { 
              0% { transform: rotate(0deg); } 
              100% { transform: rotate(360deg); } 
            }
          `
        }} />
      </body>
    </html>
  );
}
